class ErrorBoundary extends React.Component {
  state = { error: null }
  static getDerivedStateFromError(error) {
    return { error } // 渲染期切到降级 UI
  }
  componentDidCatch(error, info) {
    report(error, info) // 上报；捕不到事件/异步里的抛错
  }
  render() {
    if (this.state.error) return <Fallback />
    return this.props.children
  }
}

const Page = lazy(() => import('./Page')) // 路由/模块级拆包

export function App() {
  return (
    <ErrorBoundary> {/* 加载失败要边界，Suspense 不管 error */}
      <Suspense fallback={<Skeleton />}>
        <Page />
      </Suspense>
    </ErrorBoundary>
  )
}
